package com.terminal.port;

import javafx.scene.paint.Color;
import java.time.LocalDateTime;

/**
 * Observer interface for events generated by {@link PortSession}.
 *
 * <p><b>Thread Safety:</b> All methods are invoked from the background I/O thread.</p>
 */
public interface SessionListener {
    void portStateChanged(PortID portID, boolean isOpen);
    void logMessage(PortID portID, String message, LogType type, LocalDateTime time);

    void setControlSignal(PortID portID, String signal, boolean state);                 // RTS/DTR writing
    void getControlSignal(PortID portID, ControlSignal signal, boolean state);          // CTS/DSR reading

    void utilEvent(PortID portID, String message, LogType type, LocalDateTime time);
    void counterUpdate(PortID portID, int remainingTimes);

    void scriptStateChanged(PortID portId, boolean isBusy);

    enum LogType {
        TX(Color.BLACK),
        RX(Color.BLACK),
        INFO(Color.BLACK),

        WARNING(Color.DARKGOLDENROD),
        ERROR(Color.RED),

        SYSTEM(Color.GREY),
        PORT_OPENED(Color.GREEN),
        PORT_CLOSED(Color.CORNFLOWERBLUE),

        UTIL_STARTED(Color.DARKCYAN),
        UTIL_STOPPING(Color.DARKBLUE),

        BLOCK_END(Color.DIMGRAY),

        SPACE(Color.GREY);

        private final Color color;

        LogType(Color color){
            this.color = color;
        }

        public Color getColor(){
            return color;
        }

    }
    enum ControlSignal { RTS, CTS, DTR, DSR }
}
